      "C08A 4G OBD 即插即用 GPS 定位器": "C08A 4G OBD plug-and-play GPS tracker",
      "C08A 是一款 4G OBD 即插即用车载 GPS 定位器，支持免接线安装、实时定位、轨迹回放、断电报警、超速报警和震动报警。": "C08A is a 4G OBD plug-and-play vehicle GPS tracker that supports wire-free installation, real-time tracking, route playback, power-off alarm, overspeed alarm, and vibration alarm.",
      "4G OBD": "4G OBD",
      "即插即用": "Plug and Play",
      "免接线": "Wire-free Installation",
      "C08A 是一款 4G OBD 免接线车载 GPS 定位器，直接插入车辆 OBD 接口即可使用，适合临时车队、私家车、二手车、租赁车辆和快速部署项目。": "C08A is a 4G OBD wire-free vehicle GPS tracker that works by plugging directly into the vehicle OBD port. It is suitable for temporary fleets, private cars, used cars, rental vehicles, and fast-deployment projects.",
      "C08A，49.5 x 34 x 39 mm，约 41g": "C08A, 49.5 x 34 x 39 mm, about 41g",
      "OBD 接口供电，12-24V DC，内置 90mAh 3.7V 后备电池": "OBD port power supply, 12-24V DC, built-in 90mAh 3.7V backup battery",
      "支持实时定位、轨迹回放、电子围栏和车队管理": "Supports real-time tracking, route playback, geofencing, and fleet management",
      "支持断电、超速、位移、震动和围栏报警": "Supports power-off, overspeed, displacement, vibration, and geofence alarms",
      "OBD 即插即用": "OBD Plug and Play",
      "直接插入车辆 OBD 接口使用，无需拆车接线，适合快速部署和临时项目安装。": "Plug directly into the vehicle OBD port without dismantling or wiring, suitable for fast deployment and temporary project installation.",
      "4G 内置天线": "Built-in 4G Antenna",
      "采用 4G 内置天线和高集成设计，支持 2G + 4G 网络通信。": "Uses a built-in 4G antenna and highly integrated design, supporting 2G + 4G network communication.",
      "支持实时位置更新和定时回传，可通过平台查看车辆经纬度和运行状态。": "Supports real-time location updates and scheduled reporting, allowing the platform to view vehicle coordinates and operating status.",
      "支持历史轨迹回放，资料标注可回放 90 天驾驶轨迹、速度、方向和停留时间。": "Supports historical route playback; the document notes playback of 90 days of driving routes, speed, direction, and stop time.",
      "支持断电、超速、位移、震动和电子围栏报警，便于车辆异常事件管理。": "Supports power-off, overspeed, displacement, vibration, and geofence alarms for abnormal vehicle event management.",
      "支持一个手机管理多个设备，或一个设备被多个手机管理，适合小型车队和渠道项目。": "Supports one phone managing multiple devices, or one device managed by multiple phones, suitable for small fleets and channel projects.",
      "临时车队": "Temporary Fleets",
      "适合短期项目、临时车辆和快速上线的车队定位管理。": "Suitable for short-term projects, temporary vehicles, and fast-launch fleet tracking management.",
      "私家车定位": "Private Car Tracking",
      "适合私家车防盗、实时位置查看、超速提醒和电子围栏管理。": "Suitable for private car anti-theft, real-time location viewing, overspeed reminders, and geofence management.",
      "二手车管理": "Used Car Management",
      "适合二手车、试驾车和待售车辆的位置监管与异常提醒。": "Suitable for location supervision and abnormal reminders for used cars, test-drive vehicles, and vehicles for sale.",
      "适合租赁车辆快速安装定位，帮助掌握车辆位置和异常用车情况。": "Suitable for fast installation and tracking of rental vehicles, helping monitor vehicle location and abnormal usage.",
      "C08A 4G OBD 即插即用 GPS 定位器采用 OBD 接口免接线安装，集成 4G 通信、GPS 定位、内置天线和精密震动传感器。设备支持实时定位、定时回传、轨迹回放、电子围栏、断电报警、超速报警、位移报警、震动报警、盲区补偿和弯道修正。内置 90mAh 3.7V 后备电池，可在主电源断开时上传报警信息，适合临时车队、私家车、二手车、租赁车辆和快速部署定位项目。": "The C08A 4G OBD plug-and-play GPS tracker uses wire-free OBD port installation and integrates 4G communication, GPS tracking, built-in antennas, and a precision vibration sensor. It supports real-time tracking, scheduled reporting, route playback, geofencing, power-off alarm, overspeed alarm, displacement alarm, vibration alarm, blind-spot compensation, and curve correction. The built-in 90mAh 3.7V backup battery can upload alarm information when the main power is disconnected, making it suitable for temporary fleets, private cars, used cars, rental vehicles, and fast-deployment tracking projects.",
