      "点烟器 GPS 定位器": "Cigarette Lighter GPS Tracker",
      "C036 4G 全网通车充 GPS 定位终端": "C036 4G all-network cigarette lighter GPS tracking terminal",
      "C036 通过车辆点烟器接口供电，支持 4G 全网通通信、GPS/BDS/LBS 定位、震动报警、超速报警和拆除报警，适合免接线车辆定位项目。": "C036 is powered through the vehicle cigarette lighter socket and supports 4G all-network communication, GPS/BDS/LBS positioning, vibration alarm, overspeed alarm, and removal alarm. It is suitable for wire-free vehicle tracking projects.",
      "C036": "C036",
      "点烟器供电": "Cigarette Lighter Powered",
      "C036 是一款面向车联网的 4G 全网通车充定位终端，通过车辆点烟器接口供电，采用内置天线、3 轴传感器和智能省电唤醒设计，适合无需拆车接线的车辆定位管理。": "C036 is a 4G all-network car charger tracking terminal designed for connected vehicle applications. It is powered through the vehicle cigarette lighter socket and uses built-in antennas, a 3-axis sensor, and intelligent power-saving wake-up design for vehicle tracking without dismantling or wiring.",
      "C036，85 x 49.2 x 26 mm，约 41g": "C036, 85 x 49.2 x 26 mm, about 41g",
      "点烟器接口供电，DC 9V - 32V，内置 50mAh 3.7V 聚合物电池": "Cigarette lighter socket power, DC 9V - 32V, built-in 50mAh 3.7V polymer battery",
      "支持 GPS/BDS/LBS 定位、AGPS 快速定位和定时数据回传": "Supports GPS/BDS/LBS positioning, AGPS fast positioning, and scheduled data reporting",
      "支持震动、超速、拆除、断电、电子围栏和盲区补传": "Supports vibration, overspeed, removal, power-off, geofence alerts, and blind-spot data retransmission",
      "点烟器免接线安装": "Cigarette Lighter Wire-free Installation",
      "通过车辆点烟器接口供电，不需要拆车布线，适合临时车辆、租赁车辆和快速部署项目。": "Powered through the vehicle cigarette lighter socket without dismantling or wiring, suitable for temporary vehicles, rental vehicles, and fast-deployment projects.",
      "4G 全网通通信": "4G All-network Communication",
      "支持 LTE-FDD、LTE-TDD 与 GSM 频段，内置通信天线，支持 TCP/IP 数据传输和域名/IP 服务器连接。": "Supports LTE-FDD, LTE-TDD, and GSM bands with a built-in communication antenna, TCP/IP data transmission, and domain/IP server connection.",
      "GPS/BDS 双星定位": "GPS/BDS Dual-satellite Positioning",
      "内置 GPS/BDS 定位模块和抗干扰陶瓷天线，支持 GPS、北斗、LBS 以及 AGPS 快速定位跟踪。": "Built-in GPS/BDS positioning module and anti-interference ceramic antenna support GPS, BeiDou, LBS, and AGPS fast positioning.",
      "智能省电唤醒": "Intelligent Power-saving Wake-up",
      "内置 3 轴传感器，静止熄火状态默认每 5 分钟上传，运动点火状态默认每 20 秒上传。": "Built-in 3-axis sensor; by default, it reports every 5 minutes when stationary with ignition off and every 20 seconds when moving with ignition on.",
      "多重异常报警": "Multiple Abnormal Alerts",
      "支持震动报警、超速报警、拆除报警、断电报警和电子围栏进出提醒，便于车辆异常事件管理。": "Supports vibration alarm, overspeed alarm, removal alarm, power-off alarm, and geofence entry/exit reminders for abnormal vehicle event management.",
      "盲区数据补传": "Blind-spot Data Retransmission",
      "内置存储芯片，可在无线信号弱或干扰严重时暂存车辆运行数据，网络恢复后自动补传。": "The built-in storage chip can temporarily save vehicle operation data when wireless signals are weak or heavily interfered with, then retransmit it after network recovery.",
      "适合企业车队、车辆服务商和 4S 店进行免接线定位、行程追踪和异常提醒。": "Suitable for enterprise fleets, vehicle service providers, and 4S stores for wire-free tracking, trip tracing, and abnormal alerts.",
      "适合租赁车辆、临时车辆和短期项目快速安装定位，减少拆装成本。": "Suitable for fast installation and tracking of rental vehicles, temporary vehicles, and short-term projects, reducing installation and removal costs.",
      "出租车与客运车辆": "Taxi and Passenger Vehicles",
      "适用于出租车、客运车辆和轻量车队的实时定位、超速提醒和轨迹管理。": "Suitable for real-time tracking, overspeed reminders, and route management for taxis, passenger vehicles, and lightweight fleets.",
      "新能源与个人车辆": "New Energy and Personal Vehicles",
      "适合个人车辆、电动新能源车辆和无需复杂安装的车载定位管理。": "Suitable for personal vehicles, electric new-energy vehicles, and onboard tracking management without complex installation.",
      "C036 点烟器 GPS 定位器是一款 4G 全网通车充定位终端，融合 4G 无线通信技术与 GPS/BDS 卫星导航定位技术。设备采用工业级高集成度内置天线设计，内置 3 轴加速度传感器和 50mAh 备用电池，支持震动报警、超速报警、拆除报警、断电报警、电子围栏、历史轨迹、盲区数据补传、远程参数配置和在线升级。它适合保险、企业车队、汽车厂商/4S 店、个人用户、新能源车辆、客运车辆、出租车和租赁车辆等无需拆车接线的定位项目。": "The C036 cigarette lighter GPS tracker is a 4G all-network car charger tracking terminal that combines 4G wireless communication with GPS/BDS satellite navigation technology. It uses an industrial-grade highly integrated built-in antenna design, a built-in 3-axis accelerometer, and a 50mAh backup battery. It supports vibration alarm, overspeed alarm, removal alarm, power-off alarm, geofencing, route history, blind-spot data retransmission, remote parameter configuration, and online upgrade. It is suitable for insurance, enterprise fleets, automobile manufacturers/4S stores, individual users, new-energy vehicles, passenger vehicles, taxis, rental vehicles, and other tracking projects without vehicle wiring.",
