      "K5 是一款超低待机功耗的 4G 无线定位终端，可搭配项圈用于牛羊和牧场定位管理，支持 GPS、北斗、LBS、WiFi 四模定位、电子围栏、振动唤醒和低电报警。": "K5 is an ultra-low-standby-power 4G wireless tracking terminal that can be used with a collar for cattle, sheep, and ranch management. It supports GPS, BeiDou, LBS, Wi-Fi four-mode positioning, geofencing, vibration wake-up, and low-battery alerts.",
      "K5，75 x 57 x 31.5 mm，约 199g": "K5, 75 x 57 x 31.5 mm, about 199g",
      "10000mAh 3.8V 聚合物电池，低功耗待机": "10000mAh 3.8V polymer battery, low-power standby",
      "支持 GPS + 北斗 + LBS + WiFi 四模定位": "Supports GPS + BeiDou + LBS + Wi-Fi four-mode positioning",
      "支持拆除、震动、位移、低电、出围栏和超速报警": "Supports removal, vibration, displacement, low-battery, geofence-exit, and overspeed alerts",
      "项圈式佩戴": "Collar Wearing",
      "可搭配项圈用于牛羊佩戴式定位，适合牧场、农场和放牧区域的牲畜位置管理。": "Can be used with a collar for wearable cattle and sheep tracking, suitable for livestock location management in ranches, farms, and grazing areas.",
      "四模定位": "Four-mode Positioning",
      "支持 GPS、北斗、LBS 和 WiFi 多重定位，可根据现场信号环境组合使用。": "Supports GPS, BeiDou, LBS, and Wi-Fi multi-positioning, which can be combined according to the field signal environment.",
      "低功耗长待机": "Low-power Long Standby",
      "内置 10000mAh 3.8V 聚合物电池，支持低功耗数据传输、潜伏定位和振动唤醒。": "Built-in 10000mAh 3.8V polymer battery supports low-power data transmission, latent positioning, and vibration wake-up.",
      "可为牧场、围栏区或放牧范围设置电子围栏，离开指定范围后触发提醒。": "Geofences can be set for ranches, fenced areas, or grazing ranges, triggering reminders when leaving the specified area.",
      "支持拆除报警、震动报警、位移报警、低电报警、出围栏报警和超速报警。": "Supports removal alarm, vibration alarm, displacement alarm, low-battery alarm, geofence-exit alarm, and overspeed alarm.",
      "IP65 防护": "IP65 Protection",
      "外壳采用 ABS 塑料，支持 IP65 防护等级，适合户外牧场和移动资产使用环境。": "The housing uses ABS plastic and supports IP65 protection, suitable for outdoor ranch and mobile asset environments.",
      "牛羊定位管理": "Cattle and Sheep Tracking Management",
      "适合牛、羊等牲畜佩戴式定位，帮助牧场掌握分布位置和活动范围。": "Suitable for wearable tracking of cattle, sheep, and other livestock, helping ranches monitor distribution and activity range.",
      "牧场与放牧区": "Ranches and Grazing Areas",
      "用于牧场、农场和开放式放牧区域的牲畜追踪、围栏提醒和离群管理。": "Used for livestock tracking, fence reminders, and separation management in ranches, farms, and open grazing areas.",
      "贵重物品资产管理": "Valuable Asset Management",
      "设备也可用于高价值移动资产定位，支持低功耗待机和异常移动提醒。": "The device can also be used for high-value mobile asset tracking, supporting low-power standby and abnormal movement reminders.",
      "货运与车辆临时追踪": "Freight and Temporary Vehicle Tracking",
      "规格资料也覆盖货运车辆、租赁车辆和客运车辆等临时定位场景。": "The specification also covers temporary tracking scenarios such as freight vehicles, rental vehicles, and passenger vehicles.",
      "K5 牛羊项圈定位器是一款超低待机功耗 4G 无线定位终端，结合北斗、GPS、LBS 和 WiFi 多重定位系统，可按场景组合使用。设备支持 LTE-Cat.1 低功耗数据传输，具备实时定位、潜伏定位、振动唤醒、计步定位、历史轨迹回放、电子围栏、多车管理、低电提醒和多种异常报警能力。K5 可搭配项圈用于牛羊定位管理，也可用于贵重物品、货运车辆和临时资产定位项目。": "The K5 cattle and sheep collar tracker is an ultra-low-standby-power 4G wireless tracking terminal that combines BeiDou, GPS, LBS, and Wi-Fi positioning systems for scenario-based use. It supports LTE Cat.1 low-power data transmission, real-time tracking, latent positioning, vibration wake-up, step-count tracking, route playback, geofencing, multi-vehicle management, low-battery reminders, and multiple abnormal alerts. K5 can be used with a collar for cattle and sheep tracking, and also for valuable items, freight vehicles, and temporary asset tracking projects.",
      "4G 无线项圈 GPS 定位终端": "4G wireless collar GPS tracking terminal",
