      "英文 DOCX 规格书，包含 K5 功能、应用领域、设备参数、通信定位参数和外形规格。": "English DOCX specification covering K5 functions, application fields, device parameters, communication and positioning specifications, and outline data.",
      "K5 产品参数图": "K5 Product Parameter Image",
      "JPG 参数图，包含 K5 产品描述、功能特性、可支持功能和技术参数表。": "JPG parameter image covering K5 product description, features, supported functions, and technical parameter table.",
      "下载参数图": "Download Parameter Image",
      "太阳能牲畜追踪器": "Solar Livestock Tracker",
      "Q1-NY-2W 太阳能牛羊 GPS 追踪器": "Q1-NY-2W solar cattle and sheep GPS tracker",
      "Q1-NY-2W / NY 太阳能大容量定位器支持太阳能辅助供电、GPS/北斗/WiFi 定位和 10000mAh/20000mAh 电池配置，适合户外牧场和长时间放牧场景。": "The Q1-NY-2W / NY solar high-capacity tracker supports solar-assisted power, GPS/BeiDou/Wi-Fi positioning, and 10000mAh/20000mAh battery options for outdoor ranches and long-duration grazing scenarios.",
      "Q1-NY-2W": "Q1-NY-2W",
      "大容量电池": "High-capacity Battery",
      "Q1-NY-2W / NY": "Q1-NY-2W / NY",
      "10000mAh / 20000mAh": "10000mAh / 20000mAh",
      "GPS / 北斗 / WiFi": "GPS / BeiDou / Wi-Fi",
      "Q1-NY-2W / NY 是一款面向户外牧场和长期放牧场景的太阳能大容量 GPS 定位器，支持 TDD/FDD/GSM 移动网络、GPS 定位、北斗定位和 WiFi 定位。": "Q1-NY-2W / NY is a solar high-capacity GPS tracker for outdoor ranches and long-duration grazing scenarios. It supports TDD/FDD/GSM mobile networks, GPS positioning, BeiDou positioning, and Wi-Fi positioning.",
      "Q1-NY-2W / NY，122 x 84 x 48.5 mm": "Q1-NY-2W / NY, 122 x 84 x 48.5 mm",
      "10000mAh / 20000mAh 大容量电池，太阳能辅助供电": "10000mAh / 20000mAh high-capacity battery with solar-assisted power",
      "支持 GPS、北斗、WiFi 定位和智能省电定位": "Supports GPS, BeiDou, Wi-Fi positioning, and intelligent power-saving positioning",
      "支持 Gsensor、Type-C、LED 指示灯、智能唤醒/休眠和 FOTA": "Supports G-sensor, Type-C, LED indicators, intelligent wake/sleep, and FOTA",
      "太阳能辅助供电": "Solar-assisted Power",
      "设备结合太阳能与大容量电池设计，适合户外牧场、农场和长时间放牧管理场景。": "The device combines solar power and a high-capacity battery for outdoor ranches, farms, and long-duration grazing management scenarios.",
      "支持 10000mAh / 20000mAh 电池配置，可根据项目续航需求选择不同容量版本。": "Supports 10000mAh / 20000mAh battery configurations, allowing different capacity versions to be selected by project endurance needs.",
      "多重定位": "Multi-positioning",
      "支持 GPS、北斗和 WiFi 定位，便于在户外牧场和复杂环境中获取牲畜或设备位置。": "Supports GPS, BeiDou, and Wi-Fi positioning to obtain livestock or equipment location in outdoor ranches and complex environments.",
      "支持 TDD/FDD/GSM 移动网络接入，覆盖移动、联通、电信等网络环境。": "Supports TDD/FDD/GSM mobile network access, covering China Mobile, China Unicom, China Telecom, and similar network environments.",
      "智能唤醒休眠": "Intelligent Wake and Sleep",
      "支持定时或 Gsensor 触发的智能唤醒/休眠，并支持定时定位、智能定位和超级省电定位。": "Supports scheduled or G-sensor-triggered intelligent wake/sleep, plus scheduled positioning, intelligent positioning, and ultra power-saving positioning.",
      "户外硬件配置": "Outdoor Hardware Configuration",
      "配备 LED 指示灯、Nano SIM 侧插接口、Type-C 接口、看门狗和内置天线，便于户外部署和维护。": "Equipped with LED indicators, side-insert Nano SIM interface, Type-C interface, watchdog, and built-in antennas for outdoor deployment and maintenance.",
      "适合牧场、农场和开放式放牧区域的牛羊位置追踪、活动范围管理和长期部署。": "Suitable for cattle and sheep location tracking, activity range management, and long-term deployment in ranches, farms, and open grazing areas.",
      "用于牛、羊等牲畜定位，帮助牧场掌握牲畜位置和移动状态。": "Used for positioning cattle, sheep, and other livestock, helping ranches monitor livestock location and movement status.",
      "户外资产追踪": "Outdoor Asset Tracking",
      "适合长期放置在户外的移动资产、设备和高价值物品定位管理。": "Suitable for tracking mobile assets, equipment, and high-value items placed outdoors for long periods.",
      "低维护长期部署": "Low-maintenance Long-term Deployment",
      "太阳能辅助供电和大容量电池组合，适合不便频繁充电或维护的项目现场。": "The combination of solar-assisted power and high-capacity battery is suitable for project sites where frequent charging or maintenance is inconvenient.",
      "Q1-NY-2W / NY 太阳能牲畜追踪器是一款面向户外牧场、放牧区和长期资产监管场景的太阳能大容量定位终端。设备支持 TDD/FDD/GSM 移动网络，支持 GPS、北斗和 WiFi 定位，内置 Gsensor、Nano SIM 接口、Type-C 接口、LED 指示灯和看门狗能力。通过太阳能辅助供电和 10000mAh / 20000mAh 电池配置，可用于牛羊定位管理、户外设备追踪和低维护长期部署项目。": "The Q1-NY-2W / NY solar livestock tracker is a solar high-capacity tracking terminal for outdoor ranches, grazing areas, and long-term asset supervision. It supports TDD/FDD/GSM mobile networks, GPS, BeiDou, and Wi-Fi positioning, with built-in G-sensor, Nano SIM interface, Type-C interface, LED indicators, and watchdog capability. With solar-assisted power and 10000mAh / 20000mAh battery options, it can be used for cattle and sheep tracking, outdoor equipment tracking, and low-maintenance long-term deployment projects.",
      "太阳能大容量 GPS 定位终端": "Solar high-capacity GPS tracking terminal",
