      "中文 DOCX 规格书，包含 NY 太阳能产品参数、结构尺寸、网络频段、电源特性、硬件功能和软件功能。": "Chinese DOCX specification covering NY solar product parameters, structure dimensions, network bands, power characteristics, hardware functions, and software functions.",
