      "英文 DOCX 规格书，包含 NY 太阳能产品参数、通信网络、GPS/WiFi 定位、电源特性和硬件软件功能。": "English DOCX specification covering NY solar product parameters, communication networks, GPS/Wi-Fi positioning, power characteristics, and hardware/software functions.",
      "防水盒牛羊追踪器": "Waterproof Box Cattle and Sheep Tracker",
      "C035 4G 防水盒牛羊 GPS 定位器": "C035 4G waterproof box cattle and sheep GPS tracker",
      "C035 是一款面向牛羊放牧管理的 4G 全网通智能定位终端，内置 20000mAh 电池、3 轴传感器和 IP67 防水盒外壳，支持 GPS/BDS/GLONASS 多重定位。": "C035 is a 4G all-network smart tracking terminal for cattle and sheep grazing management. It has a built-in 20000mAh battery, 3-axis sensor, IP67 waterproof box housing, and supports GPS/BDS/GLONASS positioning.",
      "C035": "C035",
      "20000mAh": "20000mAh",
      "IP67 防水盒": "IP67 Waterproof Box",
      "20000mAh 3.7V 聚合物电池": "20000mAh 3.7V polymer battery",
      "C035 是一款专为牛羊放牧和户外资产管理打造的 4G 全网通智能定位终端，采用防水盒结构和全内置天线设计，支持 GPS/BDS/GLONASS、AGPS、LBS 多重定位。": "C035 is a 4G all-network smart tracking terminal built for cattle and sheep grazing and outdoor asset management. It uses a waterproof box structure, fully built-in antennas, and supports GPS/BDS/GLONASS, AGPS, and LBS positioning.",
      "C035，110 x 77 x 46 mm，约 476.5g": "C035, 110 x 77 x 46 mm, about 476.5g",
      "20000mAh 3.7V 聚合物电池，适合长时间户外部署": "20000mAh 3.7V polymer battery, suitable for long-term outdoor deployment",
      "支持 GPS/BDS/GLONASS + AGPS + LBS 多重定位": "Supports GPS/BDS/GLONASS + AGPS + LBS multi-positioning",
      "IP67 防护，内置 3 轴传感器，支持震动报警和多工作模式": "IP67 protection, built-in 3-axis sensor, vibration alarm, and multiple working modes",
      "防水盒结构": "Waterproof Box Structure",
      "设备采用 ABS 塑料外壳和 IP67 防护设计，适合牧场、放牧区和户外长期佩戴或固定部署。": "The device uses an ABS plastic housing and IP67 protection design, suitable for ranches, grazing areas, and long-term outdoor wearable or fixed deployment.",
      "20000mAh 大容量电池": "20000mAh High-capacity Battery",
      "内置 20000mAh 3.7V 聚合物电池，面向牛羊放牧和户外项目的长周期定位需求。": "Built-in 20000mAh 3.7V polymer battery for long-cycle tracking needs in cattle and sheep grazing and outdoor projects.",
      "支持 GPS、BDS、GLONASS、AGPS 和 LBS 定位能力，可根据现场信号环境组合使用。": "Supports GPS, BDS, GLONASS, AGPS, and LBS positioning, which can be combined according to the field signal environment.",
      "四种工作模式": "Four Working Modes",
      "支持连续定位、正常模式、省电模式和待机模式，用户可通过指令切换定位频率和功耗策略。": "Supports continuous positioning, normal mode, power-saving mode, and standby mode. Users can switch positioning frequency and power strategy through commands.",
      "报警与围栏": "Alerts and Geofencing",
      "支持电子围栏、震动报警、报警短信/电话提醒和平台报警上报，便于牲畜异常活动管理。": "Supports geofencing, vibration alarm, alarm SMS/call notification, and platform alarm upload for abnormal livestock activity management.",
      "离线补传与远程配置": "Offline Retransmission and Remote Configuration",
      "内置大容量存储芯片，支持盲区数据补传、在线远程升级和远程参数配置。": "Built-in high-capacity storage chip supports blind-spot data retransmission, online remote upgrade, and remote parameter configuration.",
      "牛羊放牧管理": "Cattle and Sheep Grazing Management",
      "用于牛、羊等牲畜的户外定位和活动范围监控，帮助牧场掌握放牧分布和异常移动。": "Used for outdoor tracking and activity range monitoring of cattle, sheep, and other livestock, helping ranches understand grazing distribution and abnormal movement.",
      "适合牧场、农场和开放式放牧区域的长时间定位、电子围栏和离群提醒项目。": "Suitable for long-duration tracking, geofencing, and separation reminder projects in ranches, farms, and open grazing areas.",
      "可用于货物、设备和户外移动资产定位，支持低功耗待机和跨区域追踪。": "Can be used for cargo, equipment, and outdoor mobile asset tracking, supporting low-power standby and cross-region tracking.",
      "客运与临时车辆": "Passenger and Temporary Vehicles",
      "资料应用领域覆盖客运车辆等临时定位场景，可按项目需求确认安装方式和使用模式。": "The specification application fields include temporary tracking scenarios such as passenger vehicles; installation and usage modes can be confirmed by project needs.",
      "C035 防水盒牛羊追踪器是一款针对牛羊定位管理设计的 4G 全网通智能定位终端。设备融合 4G 无线通信、GPS/BDS/GLONASS 卫星定位、AGPS、LBS 和 3 轴传感器能力，支持实时定位、震动报警、电子围栏、点名定位、历史轨迹、盲区数据补传和远程参数配置。设备内置 20000mAh 3.7V 聚合物电池，外壳尺寸为 110 x 77 x 46 mm，重量约 476.5g，防护等级 IP67，适合牛羊放牧、户外牧场和长期户外资产监管。": "The C035 waterproof box cattle and sheep tracker is a 4G all-network smart tracking terminal designed for cattle and sheep management. It combines 4G wireless communication, GPS/BDS/GLONASS satellite positioning, AGPS, LBS, and a 3-axis sensor, supporting real-time tracking, vibration alarm, geofencing, roll-call positioning, route history, blind-spot data retransmission, and remote parameter configuration. It has a built-in 20000mAh 3.7V polymer battery, a 110 x 77 x 46 mm housing, about 476.5g weight, IP67 protection, and is suitable for cattle and sheep grazing, outdoor ranches, and long-term outdoor asset supervision.",
      "4G 防水盒牛羊 GPS 定位终端": "4G waterproof box cattle and sheep GPS tracking terminal",
      "110 x 77 x 46 mm": "110 x 77 x 46 mm",
      "约 476.5g": "About 476.5g",
