      "<2m（1σ）": "<2m (1σ)",
      "C035 防水盒牛羊追踪器中文规格书": "C035 Waterproof Box Cattle and Sheep Tracker Chinese Specification",
      "中文 DOCX 规格书，包含 C035 产品介绍、工作模式、功能特点、电池参数、通信频段、定位参数和外形规格。": "Chinese DOCX specification covering C035 product introduction, working modes, features, battery parameters, communication bands, positioning parameters, and outline specifications.",
      "C035 防水盒牛羊追踪器英文规格书": "C035 Waterproof Box Cattle and Sheep Tracker English Specification",
      "英文 DOCX 规格书，包含 C035 产品介绍、应用领域、工作逻辑、功能特点、电气参数、通信定位参数和外形规格。": "English DOCX specification covering C035 product introduction, application fields, working logic, features, electrical parameters, communication and positioning parameters, and outline specifications.",
      "4G-温感M7": "4G Temperature M7",
      "4G-温感M7 无线超长待机资产定位终端": "4G Temperature M7 wireless ultra-long standby asset tracking terminal",
      "4G-温感M7 支持温感、光感拆机报警、GPS/BDS/GLONASS + WIFI + LBS 多重定位和干电池超长待机，适合移动资产长期部署。": "4G Temperature M7 supports temperature sensing, light-sensor tamper alarm, GPS/BDS/GLONASS + Wi-Fi + LBS positioning, and dry-battery ultra-long standby for long-term mobile asset deployment.",
      "面向跨境运输、集装箱、货柜和全球移动资产，支持跨区域位置追踪和异常移动提醒。": "Designed for cross-border transport, containers, cargo boxes, and global mobile assets, supporting cross-region location tracking and abnormal movement alerts.",
      "GF200LS 3 年长待机强磁资产定位器": "GF200LS 3-year long-standby magnetic asset tracker",
      "GF200LS 是一款强磁吸附式长待机资产 GPS 定位器，支持 IP65 防水、光感防拆、多种工作模式和约 3 年低频上报待机。": "GF200LS is a magnetic long-standby asset GPS tracker with IP65 waterproof housing, light-sensor tamper alarm, multiple working modes, and about 3 years of low-frequency reporting standby.",
      "3 年待机": "3-year Standby",
      "强磁吸附": "Strong Magnetic Mounting",
      "GF200LS 是一款面向资产、集装箱、车辆和重型设备管理的长待机 GPS 追踪器，采用强磁吸附安装，支持 IP65 防水、光感防拆报警和多种低功耗工作模式。": "GF200LS is a long-standby GPS tracker for assets, containers, vehicles, and heavy-duty equipment. It uses magnetic mounting and supports IP65 waterproof protection, light-sensor tamper alarm, and multiple low-power working modes.",
      "GF200LS，63 x 47 x 30 mm，约 0.15kg": "GF200LS, 63 x 47 x 30 mm, about 0.15 kg",
      "2 节 CR123 干电池，默认每天一次定位约 3 年": "Two CR123 dry batteries, about 3 years at the default once-per-day positioning mode",
      "支持 GPS / 北斗 / LBS 多重定位和 Web / APP 实时查看": "Supports GPS / BeiDou / LBS positioning and real-time viewing on web platform / app",
      "IP65 防水外壳，强磁后盖，支持光感防拆报警": "IP65 waterproof housing, magnetic rear cover, and light-sensor tamper alarm",
      "3 年长待机": "3-year Long Standby",
      "基于每天一次定位上报的低功耗模式，设备可实现约 3 年待机，适合长期部署在移动资产上。": "Based on a low-power mode with one positioning report per day, the device can achieve about 3 years of standby for long-term deployment on mobile assets.",
      "强磁安装": "Magnetic Installation",
      "N54 级强磁后盖便于吸附在车辆、集装箱、设备外壳或金属资产表面，无需复杂接线。": "The N54-grade magnetic rear cover can attach to vehicles, containers, equipment housings, or metal assets without complex wiring.",
      "IP65 防水": "IP65 Waterproof",
      "防水外壳适合户外运输、仓储周转和重型车辆资产管理环境。": "The waterproof housing is suitable for outdoor transport, warehouse turnover, and heavy-duty vehicle asset management environments.",
      "光感防拆报警": "Light-sensor Tamper Alarm",
      "通过光感检测识别设备被拆开或移除的异常情况，并可向平台发送防拆报警。": "Light-sensor detection identifies abnormal device opening or removal and can send tamper alerts to the platform.",
      "多种工作模式": "Multiple Working Modes",
      "支持实时模式、间隔模式和闹钟定位模式，可根据项目需求平衡定位频率和电池寿命。": "Supports real-time mode, interval mode, and alarm-clock positioning mode to balance location frequency and battery life by project needs.",
      "平台与 APP 管理": "Platform and App Management",
      "支持通过 Web 平台和移动端 APP 查看位置、历史轨迹和设备状态，便于资产追踪管理。": "Supports location, historical route, and device status viewing through the web platform and mobile app for asset tracking management.",
      "资产与集装箱追踪": "Asset and Container Tracking",
      "适用于货柜、集装箱、移动资产和高价值设备的低频长期位置追踪。": "Suitable for low-frequency long-term location tracking of cargo boxes, containers, mobile assets, and high-value equipment.",
      "跨区域货物周转": "Cross-region Cargo Turnover",
      "用于跨区域运输、仓储周转和临时外借资产的位置追踪与异常提醒。": "Used for location tracking and abnormal reminders in cross-region transport, warehouse turnover, and temporarily loaned assets.",
      "适合汽车租赁、车辆服务店和临时车辆资产的非实时位置监管。": "Suitable for non-real-time location supervision of car rental, vehicle service shops, and temporary vehicle assets.",
      "适用于重型车辆、工程设备和户外机械的长待机资产定位管理。": "Suitable for long-standby asset tracking management of heavy-duty vehicles, engineering equipment, and outdoor machinery.",
      "GF200LS 资产 GPS 定位器是一款不可充电的强磁长待机定位终端，插入 SIM 卡后可按预设频率自动上传 GPS 位置。设备采用 ABS 防火材质外壳，内置强磁后盖和 2 节 CR123 干电池，支持 LTE-FDD / LTE-TDD / GSM 网络、GPS / 北斗 / LBS 定位、Web 平台和 APP 查看、多工作模式、低电报警、震动报警、电子围栏和光感防拆报警。适合资产/集装箱追踪、车辆租赁、车队管理、重型车辆、摩托车和电动车等低频长期监管场景。": "The GF200LS asset GPS tracker is a non-rechargeable magnetic long-standby tracking terminal. After a SIM card is inserted, it can automatically upload GPS positions at a preset frequency. It uses an ABS fireproof housing, magnetic rear cover, and two CR123 dry batteries, and supports LTE-FDD / LTE-TDD / GSM networks, GPS / BeiDou / LBS positioning, web platform and app viewing, multiple working modes, low-battery alert, vibration alert, geofencing, and light-sensor tamper alarm. It is suitable for low-frequency long-term monitoring of assets, containers, rental vehicles, fleets, heavy-duty vehicles, motorcycles, and e-bikes.",
      "强磁长待机资产 GPS 定位器": "Magnetic long-standby asset GPS tracker",
