      "跨境运输 / 集装箱 / 全球资产": "Cross-border Transport / Containers / Global Assets",
      "4G-温感M7 是面向移动资产、设备箱、冷链与仓储周转场景的无线超长待机定位终端，支持温感、光感拆机报警、CAT1 通信和多重定位。": "4G Temperature M7 is a wireless ultra-long standby tracking terminal for mobile assets, equipment boxes, cold-chain, and warehouse circulation scenarios, supporting temperature sensing, light-sensor tamper alarm, CAT1 communication, and multi-source positioning.",
      "整机尺寸 78 x 47 x 27 mm": "Device size 78 x 47 x 27 mm",
      "3V / 2800mAh 干电池，默认一天一次约 3 年": "3V / 2800mAh dry battery, about 3 years at the default once-per-day report",
      "支持 GPS/BDS/GLONASS + WIFI + LBS 多重定位": "Supports GPS/BDS/GLONASS + Wi-Fi + LBS positioning",
      "支持光感拆机报警、温感兼容和多种低功耗上报模式": "Supports light-sensor tamper alarm, temperature-sensing compatibility, and multiple low-power reporting modes",
      "温感支持": "Temperature Sensing Support",
      "支持温感能力，适合需要关注环境温度变化的移动资产和周转设备。": "Supports temperature-sensing capability for mobile assets and circulating equipment where ambient temperature changes matter.",
      "采用 3V / 2800mAh 干电池，默认一天一次上报场景下可实现约 3 年工作时间。": "Uses a 3V / 2800mAh dry battery and can work for about 3 years in the default once-per-day reporting scenario.",
      "多重定位": "Multi-source Positioning",
      "支持 GPS/BDS/GLONASS、WIFI 与 LBS，适应户外、城市和复杂网络环境。": "Supports GPS/BDS/GLONASS, Wi-Fi, and LBS for outdoor, urban, and complex network environments.",
      "光感拆机报警": "Light-sensor Tamper Alarm",
      "支持光感检测，设备从暗到亮时可触发拆机报警，用于资产防拆管理。": "Supports light-sensor detection; when the device changes from dark to bright, it can trigger a tamper alarm for asset anti-removal management.",
      "CAT1 通信": "CAT1 Communication",
      "支持 4G-LTE-CAT1，TDD-LTE B34/B39/B40/B41 频段，通讯方式 UDP/TCP 可选。": "Supports 4G-LTE-CAT1, TDD-LTE B34/B39/B40/B41 bands, and optional UDP/TCP communication.",
      "灵活上报模式": "Flexible Reporting Modes",
      "支持定时回传、星期模式、闹钟模式和追踪模式，平衡定位频率与电池寿命。": "Supports scheduled reporting, weekly mode, alarm-clock mode, and tracking mode to balance positioning frequency and battery life.",
      "冷链资产": "Cold-chain Assets",
      "适合需要温度关注的冷链箱、周转箱和移动资产定位管理。": "Suitable for tracking cold-chain boxes, circulation boxes, and mobile assets that require temperature awareness.",
      "仓储周转": "Warehouse Circulation",
      "用于设备箱、周转物料和仓储资产的周期上报、位置追踪和防拆提醒。": "Used for periodic reporting, location tracking, and tamper reminders for equipment boxes, circulating materials, and warehouse assets.",
      "跨区域资产": "Cross-region Assets",
      "适用于跨区域运输资产、货柜和长时间移动资产的位置追踪。": "Suitable for location tracking of cross-region transport assets, cargo containers, and long-duration mobile assets.",
      "高价值移动资产": "High-value Mobile Assets",
      "适合高价值设备、临时外借设备和需要低频长期监管的资产。": "Suitable for high-value equipment, temporarily loaned equipment, and assets requiring low-frequency long-term supervision.",
      "4G-温感M7 无线超长待机资产定位终端采用 UIS8850+ 硬件平台，定位模块为中科微 AT6558R 或和芯星通 UC6228，支持 GPS/BDS/GLONASS、WIFI 和 LBS 多重定位。设备采用 3V / 2800mAh 干电池供电，默认一天一次上报可工作约 3 年，支持光感拆机报警、温感兼容、拨动开关、电池插拔安装、UDP/TCP 通讯和 CAT1 网络，适合长期部署在移动资产、冷链箱、设备箱和周转物料上。": "The 4G Temperature M7 wireless ultra-long standby asset tracking terminal uses a UIS8850+ hardware platform with Zhongke Micro AT6558R or Allystar UC6228 positioning module. It supports GPS/BDS/GLONASS, Wi-Fi, and LBS positioning. Powered by a 3V / 2800mAh dry battery, it can work for about 3 years with the default once-per-day reporting setting. It supports light-sensor tamper alarm, temperature-sensing compatibility, slide switch, plug-in battery installation, UDP/TCP communication, and CAT1 network, making it suitable for long-term deployment on mobile assets, cold-chain boxes, equipment boxes, and circulating materials.",
      "无线超长待机温感资产定位终端": "Wireless ultra-long standby temperature asset tracking terminal",
