      "适用于车队、物流、租赁车辆和企业车辆管理的 4G 有线 GPS 定位终端": "A 4G hardwired GPS terminal for fleets, logistics, rental vehicles, and enterprise vehicle management",
      "9-90V 宽电压": "9-90V wide voltage",
      "LTE-FDD B1/B2/B3/B4/B5/B7/B8/B28/B66，GSM/GPRS/EDGE 850/900/1800/1900MHz": "LTE-FDD B1/B2/B3/B4/B5/B7/B8/B28/B66, GSM/GPRS/EDGE 850/900/1800/1900MHz",
      "一款面向车辆长期在线管理的 4G 有线 GPS 定位终端，支持 9-90V 宽电压供电、ACC 点火启停检测、断电报警、历史轨迹、里程统计、电子围栏、超速提醒和平台管理。": "A 4G hardwired GPS terminal for long-term online vehicle management. It supports 9-90V wide-voltage power, ACC ignition on/off detection, power-cut alerts, route history, mileage statistics, geofencing, speeding alerts, and platform management.",
      "一款面向车辆长期在线管理的 4G 有线 GPS 定位终端，可用于企业车队、物流运输、租赁车辆和工程车辆定位管理，支持实时定位、轨迹回放、电子围栏和异常报警。": "A 4G hardwired GPS terminal for long-term online vehicle management, suitable for enterprise fleets, logistics, rental vehicles, and construction vehicles, with real-time tracking, route playback, geofencing, and abnormal alerts.",
      "80 x 39 x 17 mm 小体积，约 49.1 g": "Compact 80 x 39 x 17 mm body, about 49.1 g",
      "9-90V 宽电压供电，内置 100mAh 后备电池": "9-90V wide-voltage power with built-in 100mAh backup battery",
      "支持 ACC 点火启停检测与断电报警": "Supports ACC ignition on/off detection and power-cut alerts",
      "支持历史轨迹、里程统计、电子围栏和超速提醒": "Supports route history, mileage statistics, geofencing, and speeding alerts",
      "适用于车辆长期供电定位": "Suitable for long-term vehicle-powered tracking",
      "支持实时定位与轨迹回放": "Supports real-time tracking and route playback",
      "支持电子围栏与异常报警": "Supports geofencing and abnormal alerts",
      "可对接 Web 平台、移动端 APP 与 API": "Connects to web platform, mobile app, and API",
      "4G 全网通信": "4G Multi-band Communication",
      "支持 LTE-FDD 多频段与 GSM/GPRS/EDGE 频段，适合跨区域车辆长期在线管理。": "Supports multiple LTE-FDD bands plus GSM/GPRS/EDGE bands for long-term cross-region vehicle management.",
      "宽电压供电": "Wide-voltage Power",
      "支持 9-90V 工作电压，适配多种车型和车载供电环境。": "Supports 9-90V operating voltage for different vehicle types and onboard power environments.",
      "内置后备电池": "Built-in Backup Battery",
      "内置 100mAh 3.7V 电池，可用于断电状态提示和短时状态保持。": "Built-in 100mAh 3.7V battery for power-cut status prompts and short-term state retention.",
      "ACC 点火检测": "ACC Ignition Detection",
      "支持 ACC 点火启停检测，帮助识别车辆启动、熄火和使用状态。": "Supports ACC ignition on/off detection to identify vehicle start, shutdown, and usage status.",
      "轨迹与报表": "Routes and Reports",
      "支持历史轨迹、停靠报表、里程统计和一键导航，便于车队运营追溯。": "Supports route history, parking reports, mileage statistics, and one-tap navigation for fleet operation review.",
      "报警与地图能力": "Alerts and Map Capabilities",
      "支持震动提醒、电子围栏、超速提醒、断电提醒、位置分享、卫星地图和 3D 地图。": "Supports vibration alerts, geofencing, speeding alerts, power-cut alerts, location sharing, satellite maps, and 3D maps.",
      "4G 通信": "4G Communication",
      "支持 4G 网络通信，适合跨区域车辆长期在线管理。": "Supports 4G communication for long-term cross-region vehicle management.",
      "持续上传车辆位置，方便调度中心查看车辆状态。": "Continuously uploads vehicle locations so dispatch teams can monitor status.",
      "支持历史路线查询、停留点查看和行驶里程统计。": "Supports historical route queries, stop point review, and mileage statistics.",
      "车辆进入或离开指定区域时触发提醒。": "Triggers alerts when a vehicle enters or leaves a defined area.",
      "支持断电、震动、超速、异常移动等报警能力。": "Supports power cut, vibration, speeding, and abnormal movement alerts.",
      "可接入云平台、移动端 APP 或客户自有系统。": "Can connect to cloud platform, mobile app, or customer-owned systems.",
      "用于干线运输、城市配送和企业车队定位管理。": "Used for trunk transport, urban delivery, and enterprise fleet tracking management.",
      "帮助租赁公司掌握车辆位置和异常使用情况。": "Helps rental companies monitor vehicle location and abnormal usage.",
      "适合公务车、服务车、销售车辆和运维车辆管理。": "Suitable for company cars, service vehicles, sales vehicles, and maintenance vehicles.",
      "适合工程车、货车、特种车辆等长期在线定位场景。": "Suitable for long-term online tracking of construction vehicles, trucks, and special vehicles.",
      "4G 有线定位器适合安装在车辆内部，通过 9-90V 宽电压车载电源长期供电，实现稳定在线定位。设备体积小、重量轻，内置 100mAh 后备电池，支持 ACC 点火启停检测、断电报警、震动提醒、电子围栏、超速提醒、历史轨迹、停靠报表、里程统计、网页管理、位置分享和多地图切换。适用于物流、租赁、企业车队和工程车辆等需要长期在线监管的场景。": "The 4G hardwired GPS tracker is designed for in-vehicle installation and long-term power from a 9-90V onboard supply. Its compact and lightweight body includes a 100mAh backup battery and supports ACC ignition on/off detection, power-cut alerts, vibration alerts, geofencing, speeding alerts, route history, parking reports, mileage statistics, web management, location sharing, and multi-map switching. It is suitable for logistics, rental fleets, enterprise fleets, and construction vehicles that require long-term online supervision.",
      "4G 有线定位器适合安装在车辆内部，通过车辆电源长期供电，实现稳定在线定位。设备可结合平台实现实时位置查看、历史轨迹查询、电子围栏、异常报警和基础车辆运营管理。适用于物流、租赁、企业车队和工程车辆等需要长期在线监管的场景。": "The 4G hardwired GPS tracker is designed for in-vehicle installation and long-term power from the vehicle battery. Combined with the platform, it supports real-time location viewing, route history, geofencing, abnormal alerts, and basic vehicle operation management. It is suitable for logistics, rental, enterprise fleets, and construction vehicles that require long-term online supervision.",
