      "油位传感器设备": "Fuel Level Sensor Device",
      "电容式油位传感器": "Capacitive Fuel Level Sensor",
      "电容式油位传感器采用 302/304 材质，可根据油箱高度定制杆长，适合车队、货车、工程机械和储液罐液位监测。": "The capacitive fuel level sensor uses 302/304 material, supports rod length customization by tank height, and is suitable for fleets, trucks, construction machinery, and storage tank level monitoring.",
      "电容式": "Capacitive",
      "可定制杆长": "Customizable Rod Length",
      "输入电压": "Input Voltage",
      "测量范围": "Measurement Range",
      "200-2250mm 可定制": "200-2250mm customizable",
      "接口": "Interface",
      "货车 / 工程机械 / 储液罐": "Trucks / Construction Machinery / Storage Tanks",
      "一款电容式油位传感器设备，可根据油箱高度定制杆长，支持 RS232 / RS485 通讯，适合车辆油耗、罐体液位和工程设备油量监测项目。": "A capacitive fuel level sensor device with rod length customization by tank height and RS232 / RS485 communication, suitable for vehicle fuel consumption, tank level, and construction equipment fuel monitoring projects.",
      "测量范围 200-2250mm，可按油箱高度定制": "Measurement range 200-2250mm, customizable by tank height",
      "DC5V 供电，工作电流 ≤10mA": "DC5V power supply, operating current <=10mA",
      "支持 RS232 / RS485 通讯接口，9600bit/s": "Supports RS232 / RS485 communication interface, 9600bit/s",
      "适用于柴油、汽油、轻质油、水和其他流动液体": "Suitable for diesel, gasoline, light oil, water, and other flowing liquids",
      "电容式液位检测": "Capacitive Level Detection",
      "采用电容式测量方式，用于检测油箱或罐体内液位高度变化。": "Uses capacitive measurement to detect liquid level changes inside fuel tanks or storage tanks.",
      "杆长可定制": "Customizable Rod Length",
      "传感器长度可根据油箱高度定制，资料覆盖 200-2250mm 测量范围。": "Sensor length can be customized by tank height; the documentation covers a 200-2250mm measurement range.",
      "多接口输出": "Multiple Interface Output",
      "支持 RS232 / RS485 通讯接口，可按项目对接 GPS 终端或监控主机。": "Supports RS232 / RS485 communication interfaces and can connect with GPS terminals or monitoring hosts by project.",
      "智能滤波": "Intelligent Filtering",
      "支持智能液位检测和滤波处理，适合车辆行驶晃动场景下的油位监测。": "Supports intelligent level detection and filtering, suitable for fuel level monitoring under vehicle movement and vibration.",
      "多液体适配": "Multi-liquid Compatibility",
      "可用于柴油、汽油、轻质油、低介质油品、水和其他流动液体监测。": "Can monitor diesel, gasoline, light oil, low-dielectric oil products, water, and other flowing liquids.",
      "车队油耗管理": "Fleet Fuel Consumption Management",
      "结合 GPS 平台用于油耗变化、异常耗油和车辆运营成本管理。": "Works with the GPS platform for fuel change monitoring, abnormal fuel consumption detection, and vehicle operating cost management.",
      "货车油耗监测": "Truck Fuel Consumption Monitoring",
      "用于货车、重卡和物流车辆油位变化监测，辅助识别异常油耗。": "Used to monitor fuel level changes in trucks, heavy trucks, and logistics vehicles, helping identify abnormal fuel consumption.",
      "工程机械油量监测": "Construction Machinery Fuel Level Monitoring",
      "适合挖掘机、装载机和工程设备油箱液位监控。": "Suitable for fuel tank level monitoring in excavators, loaders, and construction equipment.",
      "运输车罐体液位": "Transport Tank Level",
      "可用于运输罐体液位管理，帮助掌握液体装载和消耗变化。": "Can be used for transport tank level management to monitor loading and consumption changes.",
      "储液罐液位测量": "Storage Tank Level Measurement",
      "适合固定储罐、储油罐和其他储液容器的液位采集。": "Suitable for liquid level collection in fixed tanks, oil storage tanks, and other storage containers.",
      "油位传感器设备基于电容式液位检测原理，外壳和探杆可采用 302/304 材质，支持按油箱高度定制杆长。设备支持 DC5V 供电、低工作电流、1mm 分辨率和 RS232 / RS485 通讯接口，可与 GPS 终端或客户平台组合，用于车辆油耗、罐体液位、工程设备油量和储液容器监测。实际杆长、协议和液体类型需根据项目现场确认。": "The fuel level sensor device is based on capacitive level detection. The housing and probe rod can use 302/304 material, and the rod length can be customized by tank height. It supports DC5V power, low operating current, 1mm resolution, and RS232 / RS485 communication, and can work with GPS terminals or customer platforms for vehicle fuel consumption, tank level, construction equipment fuel, and storage container monitoring. Actual rod length, protocol, and liquid type should be confirmed by project conditions.",
      "≤10mA": "<=10mA",
