      "中文 PDF 规格书，包含电容式油位传感器介绍、应用领域、基础参数、通讯接口和安装说明。": "Chinese PDF specification covering capacitive fuel level sensor introduction, application fields, basic parameters, communication interfaces, and installation notes.",
      "油位传感器设备英文规格书": "Fuel Level Sensor Device English Specification",
