      "下载英文 PPTX": "Download English PPTX",
      "超声波油耗监测设备": "Ultrasonic Fuel Monitoring Device",
      "ZC-05 超声波油位传感器": "ZC-05 Ultrasonic Fuel Level Sensor",
      "ZC-05 超声波油位传感器采用外贴式非开孔安装，适合货车、客车、工程机械和运输罐体的油耗与液位监测。": "The ZC-05 ultrasonic fuel level sensor uses external non-drilling installation and is suitable for fuel consumption and liquid level monitoring in trucks, passenger vehicles, construction machinery, and transport tanks.",
      "非开孔安装": "Non-drilling Installation",
      "0-5V / 4-20mA 可选": "0-5V / 4-20mA Optional",
      "DC5V-36V": "DC5V-36V",
      "1-10000mm 可定制": "1-10000mm customizable",
      "RS232 / RS485 / 0-5V / 4-20mA 可选": "RS232 / RS485 / 0-5V / 4-20mA optional",
      "ZC-05 超声波油位传感器采用外贴式非开孔安装，可穿透油箱外壁进行液位检测，适合车辆油耗监测、工程设备油量管理和罐体液位采集。": "The ZC-05 ultrasonic fuel level sensor uses external non-drilling installation and can detect liquid level through the outer wall of the fuel tank. It is suitable for vehicle fuel monitoring, construction equipment fuel management, and tank level collection.",
      "ZC-05，外贴式超声波液位检测": "ZC-05, external ultrasonic level detection",
      "DC5V-36V 供电，工作电流 ≤10mA": "DC5V-36V power supply, operating current <=10mA",
      "测量范围 1-10000mm，分辨率 1mm": "Measurement range 1-10000mm, 1mm resolution",
      "支持 RS232 / RS485，0-5V / 4-20mA 可定制": "Supports RS232 / RS485, with customizable 0-5V / 4-20mA output",
      "传感器从油箱外部贴装检测，不需要在油箱上开孔，降低安装风险。": "The sensor is mounted outside the fuel tank for detection, avoiding tank drilling and reducing installation risk.",
      "超声波检测": "Ultrasonic Detection",
      "通过超声波液位检测识别油位变化，适合车辆和设备燃油监测。": "Uses ultrasonic level detection to identify fuel level changes, suitable for vehicle and equipment fuel monitoring.",
      "宽电压供电": "Wide-voltage Power",
      "支持 DC5V-36V 输入，适配多种车载和设备供电环境。": "Supports DC5V-36V input for different vehicle and equipment power environments.",
      "支持 RS232 / RS485 通讯接口，并可按项目定制 0-5V 或 4-20mA 输出。": "Supports RS232 / RS485 communication and customizable 0-5V or 4-20mA output by project.",
      "支持智能算法处理油面晃动和复杂道路工况，提升液位数据稳定性。": "Uses intelligent algorithms to handle fuel surface movement and complex road conditions, improving level data stability.",
      "复杂油箱适配": "Complex Tank Compatibility",
      "可穿透 0-5mm 铝、铁、塑料油箱，适合多类车辆油箱环境。": "Can penetrate 0-5mm aluminum, iron, and plastic fuel tanks, suitable for various vehicle tank environments.",
      "货车远程油耗监测": "Remote Truck Fuel Monitoring",
      "用于货车和重卡燃油液位变化监控，辅助识别异常耗油。": "Used to monitor fuel level changes in trucks and heavy trucks, helping identify abnormal fuel consumption.",
      "工程机械油量消耗": "Construction Machinery Fuel Consumption",
      "适合工程机械、施工设备和户外车辆的油量消耗监测。": "Suitable for fuel consumption monitoring of construction machinery, jobsite equipment, and outdoor vehicles.",
      "客运车辆燃油检测": "Passenger Vehicle Fuel Detection",
      "适合客车、班车和运输车辆的非开孔油耗监测项目。": "Suitable for non-drilling fuel monitoring projects for buses, shuttle vehicles, and transport vehicles.",
      "用于运输罐体和固定储罐液位采集，减少人工巡检成本。": "Used for liquid level collection in transport tanks and fixed storage tanks, reducing manual inspection costs.",
      "超声波油耗监测设备基于 ZC-05 外贴式超声波油位传感器资料整理，适用于需要非开孔安装的油耗与液位监测项目。设备支持 DC5V-36V 供电、1-10000mm 测量范围、1mm 分辨率、RS232 / RS485 通讯接口，并可按项目定制 0-5V 或 4-20mA 输出。安装时需结合油箱材质、厚度、液体类型和现场环境确认方案。": "The ultrasonic fuel monitoring device is based on the ZC-05 external ultrasonic fuel level sensor documentation and is suitable for fuel consumption and liquid level monitoring projects requiring non-drilling installation. It supports DC5V-36V power, 1-10000mm measurement range, 1mm resolution, RS232 / RS485 communication, and customizable 0-5V or 4-20mA output. Installation should be confirmed according to tank material, thickness, liquid type, and site conditions.",
      "产品型号": "Product Model",
      "外贴式超声波油位传感器": "External Ultrasonic Fuel Level Sensor",
      "1-10000mm，可定制": "1-10000mm, customizable",
