      "超声波油耗监测设备中文规格书": "Ultrasonic Fuel Monitoring Device Chinese Specification",
      "中文 PDF 规格书，包含 ZC-05 超声波油位传感器介绍、安装方式、技术参数和应用说明。": "Chinese PDF specification covering ZC-05 ultrasonic fuel level sensor introduction, installation method, technical parameters, and applications.",
      "超声波油耗监测设备英文规格书": "Ultrasonic Fuel Monitoring Device English Specification",
      "英文 PPTX 规格书，便于海外客户查看超声波油位传感器参数、安装方式和项目选型信息。": "English PPTX specification for overseas customers to review ultrasonic fuel level sensor parameters, installation method, and project selection information.",
      "油液监测GPS有线追踪器": "Oil Liquid Monitoring Wired GPS Tracker",
      "C003F 4G 测油 GPS 主机": "C003F 4G Fuel Monitoring GPS Host",
      "C003F 是支持外接油杆、RS232/RS485/TTL、ACC 检测和多重报警的 4G 有线车载 GPS 主机，适合油液监测与车队定位项目。": "C003F is a 4G wired vehicle GPS host supporting external fuel rods, RS232/RS485/TTL, ACC detection, and multiple alarms, suitable for fuel/liquid monitoring and fleet tracking projects.",
      "外接油杆": "External Fuel Rod",
      "断油电 / SOS / ACC / RS232/RS485/TTL": "Fuel/power cut / SOS / ACC / RS232/RS485/TTL",
      "C003F 是一款面向车联网和油液监测项目的 4G 全网通有线车载 GPS 主机，支持外接油杆、摄像头、RFID、继电器和 SOS 按键，可用于车辆定位、油耗监控、异常报警和平台化车队管理。": "C003F is a 4G all-network wired vehicle GPS host for IoV and fuel/liquid monitoring projects. It supports external fuel rods, cameras, RFID, relays, and SOS buttons for vehicle tracking, fuel monitoring, abnormal alarms, and platform-based fleet management.",
      "C003F，4G 全网通有线 GPS/BDS 定位主机": "C003F, 4G all-network wired GPS/BDS positioning host",
      "DC 9V-95V 宽电压供电，支持 ACC 与 DC 检测": "DC 9V-95V wide-voltage power input with ACC and DC detection",
      "支持 RS232/RS485/TTL，可外接油杆、摄像头和 RFID": "Supports RS232/RS485/TTL and external fuel rods, cameras, and RFID",
      "支持震动、断电、超速、SOS、非法启动和电子围栏报警": "Supports vibration, power-off, overspeed, SOS, illegal start, and geofence alarms",
      "油杆外设接入": "Fuel Rod Peripheral Access",
      "硬件可配备 232/485 接口，支持外接油杆、摄像头、RFID 等外设，适合油液监测和车联网项目。": "The hardware can be equipped with 232/485 interfaces and supports external fuel rods, cameras, RFID, and other peripherals for fuel/liquid monitoring and IoV projects.",
      "采用 SIMCOM A7670SA 通信方案，支持 LTE-FDD 多频段和 GSM 2G 频段。": "Uses the SIMCOM A7670SA communication solution and supports multi-band LTE-FDD and GSM 2G bands.",
      "GPS/北斗双星定位": "GPS/BeiDou Dual-satellite Positioning",
      "内置 GPS/BDS 双星定位模块和陶瓷天线，支持 AGPS 快速定位和同步授时。": "Built-in GPS/BDS dual-satellite positioning module and ceramic antenna, supporting AGPS fast positioning and synchronized timing.",
      "ACC 与电源检测": "ACC and Power Detection",
      "支持 ACC 检测、DC 检测、车辆点火熄火判断和电瓶低电压监测报警。": "Supports ACC detection, DC detection, ignition status recognition, and low vehicle battery voltage alarms.",
      "多重报警": "Multiple Alarms",
      "支持震动、断电、超速、SOS 紧急求救、非法启动、电子围栏和位移报警。": "Supports vibration, power-off, overspeed, SOS emergency, illegal start, geofence, and displacement alarms.",
      "盲区补传": "Blind-spot Data Retransmission",
      "内置大容量存储芯片，可在弱信号或干扰环境下缓存数据，网络恢复后自动补传。": "Built-in high-capacity storage caches data in weak-signal or interference environments and retransmits automatically after network recovery.",
      "车队油液监测": "Fleet Fuel/Liquid Monitoring",
      "适合车队车辆接入油杆进行油液变化监测、异常耗油预警和运营成本管理。": "Suitable for fleet vehicles connected to fuel rods for fuel/liquid change monitoring, abnormal consumption alerts, and operating cost management.",
      "工程机械油耗管理": "Construction Machinery Fuel Management",
      "适合工程机械和施工设备接入油杆、继电器或平台，实现定位和油耗监管。": "Suitable for construction machinery and jobsite equipment connected to fuel rods, relays, or platforms for tracking and fuel monitoring.",
      "租赁车辆风控": "Rental Vehicle Risk Control",
      "适合租赁车辆的位置监管、断电报警、电子围栏和远程风控管理。": "Suitable for rental vehicle location supervision, power-off alarms, geofencing, and remote risk control.",
      "企业车辆管理": "Enterprise Vehicle Management",
      "适合企业车队、4S 店、客运车辆、出租车和新能源车辆的日常定位管理。": "Suitable for daily tracking management of enterprise fleets, 4S stores, passenger vehicles, taxis, and new energy vehicles.",
      "油液监测GPS有线追踪器基于 C003F 4G 测油 GPS 主机资料整理，是一款面向车联网和油液监测项目的有线车载定位终端。设备融合 4G 全网通无线通信、GPS/BDS 卫星定位、3 轴传感器和智能省电唤醒机制，支持外接油杆、摄像头、RFID、断油电继电器和 SOS 按键。设备可通过平台实现车辆数据实时获取、轨迹定位、油液监测、电子围栏、多重报警、盲区补传和远程参数配置。": "The oil liquid monitoring wired GPS tracker is based on the C003F 4G fuel monitoring GPS host documentation. It is a wired vehicle positioning terminal for IoV and fuel/liquid monitoring projects. The device combines 4G all-network wireless communication, GPS/BDS satellite positioning, a 3-axis sensor, and intelligent power-saving wakeup. It supports external fuel rods, cameras, RFID, fuel/power cut relays, and SOS buttons. Through the platform, it enables real-time vehicle data collection, route tracking, fuel/liquid monitoring, geofencing, multiple alarms, blind-spot retransmission, and remote parameter configuration.",
      "4G 测油 GPS 有线主机": "4G Fuel Monitoring Wired GPS Host",
