      "C003F Oil Liquid Monitoring Wired GPS Tracker English Specification": "C003F Oil Liquid Monitoring Wired GPS Tracker English Specification",
      "English DOCX specification covering C003F product introduction, working logic, features, hardware specifications, positioning parameters, and external interfaces.": "English DOCX specification covering C003F product introduction, working logic, features, hardware specifications, positioning parameters, and external interfaces.",
      "可配合继电器实现远程断油断电控制，适用于车辆风控、租赁和防盗场景。": "Can work with a relay for remote fuel and power cut-off control, suitable for vehicle risk control, rental, and anti-theft scenarios.",
      "730-4G-G 继电器型远程油电控制 GPS 定位终端": "730-4G-G relay-type GPS terminal for remote fuel and power control",
      "继电器型 4G GPS 追踪器，支持远程油电切断、恢复油电、ACC 开关、车辆电压监测和多种报警。": "Relay-type 4G GPS tracker supporting remote fuel and power cut-off, fuel and power restore, ACC switch, vehicle voltage monitoring, and multiple alerts.",
