      "730-4G-G 继电器型 4G GPS 追踪器，支持 8V-90V 宽电压、IP64 防护、远程油电切断与恢复、ACC 开关报警、车辆电压监测、断电报警和多星定位。": "The 730-4G-G relay-type 4G GPS tracker supports 8V-90V wide voltage, IP64 protection, remote fuel and power cut-off and restore, ACC switch alerts, vehicle voltage monitoring, power-failure alerts, and multi-constellation positioning.",
      "型号 730-4G-G，70 x 33 x 32 mm，约 65g": "Model 730-4G-G, 70 x 33 x 32 mm, about 65g",
      "8V-90V 宽电压，内置 45mAh 电池": "8V-90V wide voltage with built-in 45mAh battery",
      "IP64 防护，支持远程油电切断与恢复": "IP64 protection with remote fuel and power cut-off and restore",
      "支持 GPS + 北斗 + Glonass 全模式卫星定位": "Supports GPS + BeiDou + Glonass full-mode satellite positioning",
      "远程油电控制": "Remote Fuel and Power Control",
      "支持远程油电切断与恢复油电，适合租赁车辆、金融风控和防盗管理。": "Supports remote fuel and power cut-off and restore, suitable for rental vehicles, financial risk control, and anti-theft management.",
      "多星定位": "Multi-constellation Positioning",
      "支持 GPS + 北斗 + Glonass 全模式卫星定位，资料标注 3m（3D 模式下）定位精度。": "Supports GPS + BeiDou + Glonass full-mode satellite positioning, with 3m accuracy noted in the source sheet under 3D mode.",
      "1 秒上传能力": "1-second Upload Capability",
      "支持 1s 上传频率，也支持 10 分钟以上固定时间上传模式。": "Supports 1-second upload frequency and fixed-time upload mode for intervals longer than 10 minutes.",
      "报警体系": "Alert System",
      "支持震动、位移、超速、断电、拖车、ACC 开关和 ACC 自动布撤防报警。": "Supports vibration, displacement, overspeed, power failure, trailer, ACC switch, and ACC automatic arming/disarming alerts.",
      "盲区补传": "Blind-spot Supplementary Upload",
      "支持盲区补传、拐弯补报和网络注册显示（2G/4G），减少轨迹断点。": "Supports blind-spot supplementary upload, turning supplementary report, and network registration display (2G/4G) to reduce route gaps.",
      "远程维护": "Remote Maintenance",
      "支持车辆电压监测和远程软件升级，便于项目部署后的持续运维。": "Supports vehicle voltage monitoring and remote software upgrade for ongoing operation after deployment.",
      "适用于汽车租赁车辆的位置监管、异常报警和远程油电控制。": "Suitable for location supervision, abnormal alerts, and remote fuel and power control for car rental vehicles.",
      "适用于物流运输车辆的实时定位、历史轨迹、超速报警和断电报警管理。": "Suitable for real-time tracking, route history, overspeed alerts, and power-failure alert management for logistics vehicles.",
      "金融风控": "Financial Risk Control",
      "面向金融风控车辆，支持远程控制、位置监管、位移报警和电压监测。": "Designed for financial risk-control vehicles, supporting remote control, location supervision, displacement alerts, and voltage monitoring.",
      "私家车防盗": "Private Car Anti-theft",
      "适用于私家车防盗、异常移动提醒、拖车报警和远程恢复油电。": "Suitable for private car anti-theft, abnormal movement reminders, trailer alerts, and remote fuel/power restore.",
      "摩托车与电动车": "Motorcycles and E-bikes",
      "适用于摩托车、电动车等小型车辆的定位、防盗和异常报警。": "Suitable for positioning, anti-theft, and abnormal alerts for motorcycles, e-bikes, and other small vehicles.",
      "断油断电定位器基于 730-4G-G 继电器型 4G GPS 追踪器资料整理，适用于汽车租赁、物流运输、金融风控、私家车防盗、摩托车和电动车等场景。设备支持 8V-90V 宽电压、IP64 防护、内置 45mAh 电池、GPS + 北斗 + Glonass 全模式卫星定位、远程油电切断与恢复、ACC 开关报警、车辆电压监测、盲区补传和远程软件升级。实际远程控制策略应结合当地法规、项目安全要求和安装方案配置。": "This fuel and power cut-off tracker is organized from the 730-4G-G relay-type 4G GPS tracker sheet and is suitable for car rental, logistics, financial risk control, private car anti-theft, motorcycles, and e-bikes. It supports 8V-90V wide voltage, IP64 protection, built-in 45mAh battery, GPS + BeiDou + Glonass full-mode satellite positioning, remote fuel/power cut-off and restore, ACC switch alerts, vehicle voltage monitoring, blind-spot supplementary upload, and remote software upgrade. Actual remote-control strategy should be configured according to local regulations, project safety requirements, and installation plans.",
